import{_ as e,o as i,c as n,a2 as s}from"./chunks/framework.CWdVbaJB.js";const u=JSON.parse('{"title":"Findings & Workflows","description":"","frontmatter":{"title":"Findings & Workflows"},"headers":[],"relativePath":"security/findings.md","filePath":"security/findings.md"}'),a={name:"security/findings.md"};function d(o,t,r,l,g,c){return i(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="findings-workflows" tabindex="-1">Findings &amp; Workflows <a class="header-anchor" href="#findings-workflows" aria-label="Permalink to &quot;Findings &amp; Workflows&quot;">​</a></h1><p>Findings represent security issues detected in your AI traces. SHAVIRA provides a workflow system for triaging, assigning, and resolving findings.</p><h2 id="finding-structure" tabindex="-1">Finding Structure <a class="header-anchor" href="#finding-structure" aria-label="Permalink to &quot;Finding Structure&quot;">​</a></h2><p>Each finding contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Title</td><td>Descriptive name of the security issue</td></tr><tr><td>Severity</td><td><code>critical</code>, <code>high</code>, <code>medium</code>, or <code>low</code></td></tr><tr><td>Status</td><td>Current workflow state</td></tr><tr><td>Assignee</td><td>Team member responsible for triage</td></tr><tr><td>Detection artifacts</td><td>Sigma rules, SIEM queries, ATT&amp;CK mappings</td></tr><tr><td>Trace link</td><td>Associated trace for investigation</td></tr><tr><td>Project</td><td>Project where the finding was detected</td></tr><tr><td>Comments</td><td>Discussion thread</td></tr></tbody></table><h2 id="status-workflow" tabindex="-1">Status Workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status Workflow&quot;">​</a></h2><p>Findings progress through four states:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Open → Investigating → Resolved</span></span>
<span class="line"><span>                    → False Positive</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Open</strong></td><td>New finding, not yet triaged</td></tr><tr><td><strong>Investigating</strong></td><td>Under active investigation</td></tr><tr><td><strong>Resolved</strong></td><td>Issue confirmed and remediated</td></tr><tr><td><strong>False Positive</strong></td><td>Not a real issue</td></tr></tbody></table><p>When a finding is resolved or marked as false positive, SHAVIRA records who resolved it and when.</p><h2 id="filtering-findings" tabindex="-1">Filtering Findings <a class="header-anchor" href="#filtering-findings" aria-label="Permalink to &quot;Filtering Findings&quot;">​</a></h2><p>Use the status filter chips at the top of the findings view to show/hide findings by status. Combine with:</p><ul><li><strong>Severity filter</strong> — focus on critical/high issues first</li><li><strong>Search</strong> — fuzzy search on finding titles</li><li><strong>Assignee</strong> — see what&#39;s assigned to you or unassigned</li><li><strong>Project</strong> — scope to a specific project</li></ul><h2 id="assigning-findings" tabindex="-1">Assigning Findings <a class="header-anchor" href="#assigning-findings" aria-label="Permalink to &quot;Assigning Findings&quot;">​</a></h2><ol><li>Click a finding to open the detail panel</li><li>Use the <strong>Assignee</strong> dropdown to select a team member</li><li>The assignee receives the finding in their filtered view</li></ol><p>Unassign by selecting the empty option from the dropdown.</p><h2 id="adding-comments" tabindex="-1">Adding Comments <a class="header-anchor" href="#adding-comments" aria-label="Permalink to &quot;Adding Comments&quot;">​</a></h2><p>Open a finding&#39;s detail panel and switch to the <strong>Comments</strong> tab:</p><ol><li>Type your comment in the text area</li><li>Click <strong>Post</strong></li><li>Comments appear in chronological order with author name and timestamp</li></ol><p>Use comments to document investigation steps, share context, or request input from teammates.</p><h2 id="bulk-actions" tabindex="-1">Bulk Actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk Actions&quot;">​</a></h2><p>Select multiple findings using the checkboxes, then use the bulk action toolbar to:</p><ul><li><strong>Set status</strong> — change all selected findings to a status</li><li><strong>Assign</strong> — assign all selected findings to a user</li></ul><p>Bulk actions are audit logged with the count of affected findings.</p><h2 id="audit-trail" tabindex="-1">Audit Trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit Trail&quot;">​</a></h2><p>All finding actions are logged:</p><table tabindex="0"><thead><tr><th>Event</th><th>Logged Fields</th></tr></thead><tbody><tr><td><code>finding.status_changed</code></td><td>Old status, new status, user</td></tr><tr><td><code>finding.assigned</code></td><td>Previous assignee, new assignee</td></tr><tr><td><code>finding.commented</code></td><td>Comment author, finding ID</td></tr><tr><td><code>finding.bulk_update</code></td><td>Action type, count, user</td></tr></tbody></table>`,27)])])}const p=e(a,[["render",d]]);export{u as __pageData,p as default};
